{
  "units": [
    {
      "id": "T1",
      "verdict": "contradicted",
      "sourceIds": ["S2", "S4"],
      "reason": "S2仅允许在资源未变化时返回304且不再发送正文，S4还明确首次请求仍需获取完整资源。将这一条件性机制扩大为所有请求都能跳过资源更新，与原文矛盾。"
    },
    {
      "id": "T2",
      "verdict": "contradicted",
      "sourceIds": ["S2"],
      "reason": "S2的条件是“如果资源没有变化”，服务器“可”返回304且不再发送正文。摘要改成“即使内容已经变化”且称服务器“应”返回304，既反转了条件，也把可选行为说成必然行为。"
    },
    {
      "id": "T3",
      "verdict": "contradicted",
      "sourceIds": ["S4"],
      "reason": "S4明确首次请求仍需获取完整资源，摘要却称首次请求可以跳过正文，结论相反。"
    },
    {
      "id": "T4",
      "verdict": "unsupported",
      "sourceIds": [],
      "reason": "原文仅说明ETag的返回、条件请求、缓存验证限制及首次请求要求，没有承诺客户端始终获取最新数据，也没有保证不存在一致性问题。"
    },
    {
      "id": "T5",
      "verdict": "contradicted",
      "sourceIds": ["S1", "S3"],
      "reason": "S1说明服务器在响应中返回ETag，S3说明ETag由服务端维护并明确不能仅凭文件名判断内容变化。“ETag只是文件名”与此冲突，“不会随资源内容变化”也没有原文依据。"
    }
  ],
  "facts": [
    {
      "id": "F1",
      "status": "omitted",
      "unitIds": [],
      "reason": "摘要没有表达服务器在响应中返回ETag这一事实。"
    },
    {
      "id": "F2",
      "status": "wrong",
      "unitIds": ["T2"],
      "reason": "T2虽提到客户端携带If-None-Match以及304不发送正文，却把“资源没有变化”反转成“即使内容已经变化”，因此关键事实被错误表达。"
    },
    {
      "id": "F3",
      "status": "wrong",
      "unitIds": ["T5"],
      "reason": "原文说明ETag由服务端维护且不能仅凭文件名判断内容变化；T5却将ETag说成只是文件名，并作出其不会随内容变化的断言。"
    },
    {
      "id": "F4",
      "status": "wrong",
      "unitIds": ["T1", "T3"],
      "reason": "摘要没有准确表达该机制减少重复传输，反而声称所有请求都能跳过更新、首次请求也能跳过正文，与首次请求仍需获取完整资源相矛盾。"
    }
  ],
  "constraints": [
    {
      "id": "K1",
      "status": "violated",
      "unitIds": ["T1", "T2"],
      "reason": "该机制只以资源未变化为条件；T2明确改成内容已经变化时也返回304，T1又将适用范围扩大到所有请求。"
    },
    {
      "id": "K2",
      "status": "violated",
      "unitIds": ["T5"],
      "reason": "T5把ETag等同于文件名并据此断言其不随资源内容变化，违背了不能仅凭文件名判断内容是否变化的限制。"
    },
    {
      "id": "K3",
      "status": "violated",
      "unitIds": ["T1", "T3"],
      "reason": "T3直接声称首次请求可以跳过正文，T1的“所有请求”范围也包含首次请求，均与首次请求仍需获取完整资源相冲突。"
    }
  ],
  "clarity": {
    "clear": true,
    "nonRedundant": true,
    "reason": "摘要按结论、要点、风险和术语分段，各句含义可以理解；虽存在事实错误和范围扩大，但没有明显跨段重复，句子分别表达了不同断言。"
  }
}
